import java.util.Scanner;

public class Main {
    static long[] pw = new long[20];
    static int ans;

    static long check(long x, int[] len) {
        len[0] = 0;
        while (x >= 10) {
            x /= 10;
            len[0]++;
        }
        return x;
    }

    static void dfs(long x, int cnt) {
        if (cnt >= ans) return;
        if (x == 0) {
            ans = cnt;
            return;
        }
        int[] lenArr = new int[1];
        int t = (int) check(x, lenArr);
        int len = lenArr[0];

        // First recursive call
        dfs(Math.abs(x - pw[len] * t), cnt + t * (len + 1));
        // Second recursive call
        if (t - 1 > 0) {
            dfs(Math.abs(x - pw[len] * (t - 1)), cnt + (t - 1) * (len + 1));
        }
        // Third recursive call
        if (t > 1) {
            dfs(Math.abs(pw[len + 1] - x), cnt + (len + 2));
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        pw[0] = 1;
        for (int i = 1; i <= 18; i++) {
            pw[i] = pw[i - 1] * 10 + 1;
        }

        ans = Integer.MAX_VALUE;
        dfs(n, 0);
        System.out.println(ans);
        sc.close();
    }
}

